const askedAltBefore = chatHistory.some(h => h.role === 'assistant' && (h.message||h.content||'').includes('طريقة أخرى تقدر تخلص بيها'));
const noOtherMethod = /ماعنديش|معنديش|ماكاينش|والو|غير هادي|just|only|فقط|ماعندي والو|هادي اللي عندي/.test((d.message||'').toLowerCase()) && askedAltBefore;

let specialReply = '';
let stopChatNow = false;
let alertOverride = false;

if (chosenMethod && askedPaymentBefore) {
  specialReply = PAYMENT_METHODS[chosenMethod];
} else if (noOtherMethod) {
  specialReply = 'مرحبا 🙏 غادي يتواصل معاك مسؤول دابا باش يكمل معاك. شوية ديال الصبر 🙏';
  stopChatNow = true;
  alertOverride = true;
} else if (unavailableMethod) {
  specialReply = 'هاد الطريقة مازال ماكايناش 🙏 واش عندك شي طريقة أخرى تقدر تخلص بيها من: Cash Plus، Wafacash، CIH، Barid Bank، Binance؟';
} else if (approves && shownAccountBefore && !askedPaymentBefore) {
  specialReply = PAYMENT_ASK;
} else if (isBuying && mainProduct) {
  specialReply = PAYMENT_ASK;
}

const wantsToSee = /نشوف|نشوفو|شوف|ورني|وريني|صورة|صور|عرض|اعرض|نتفرج|montre|photo|image|show|see|خاصني|بغيت حساب|بغيت كونط|كونط|عندكم حساب|عندك حساب|account/i.test((d.message || '').toLowerCase());

let imageProduct = null;
if (!chosenMethod && !askedPaymentBefore && !isBuying && !(approves && shownAccountBefore)) {
  if (d.is_no && mainProduct) {
    const excludeId = mainProduct.json.id;
    const altByPrice = filterByPrice(available, excludeId);
    const altOthers = available.filter(p => p.json.id !== excludeId);
    imageProduct = altByPrice.length > 0 ? altByPrice[0] : (altOthers.length > 0 ? altOthers[0] : null);
  } else if ((d.intent === 'inquiry' || wantsAnother || wantsToSee) && mainProduct) {
    imageProduct = mainProduct;
  }
}

const imageUrl = getImgUrl(imageProduct) || 'NO_IMAGE';

const productInfo = mainProduct ? mainProduct.json.product_name + ' ب' + mainProduct.json.price : '';
const categoriesStr = categories.join(', ');

let instruction = '';
if (wantsToSee && mainProduct && !askedPaymentBefore && !chosenMethod) {
  instruction = 'الزبون بغا يشوف الحساب. ها هي صورة الحساب فوق 👆. اعرض: ' + productInfo + ' بجملة قصيرة حماسية واسأله واش عجبو. لا ترفض أبداً ولا تقل أنك ما تقدرش تعرض صورة - الصورة كتبان معاك.';
} else if (wantsAnother && mainProduct) {
  instruction = 'الزبون طلب حساب آخر. اعرض حساب مختلف بنفس الثمن (' + mainProduct.json.price + ') ووري أنه متوفر. اسأله: واش هادا عجبك؟';
} else if (d.is_no) {
  const altP = imageProduct || (available.filter(p=>p!==mainProduct)[0] || null);
  instruction = altP ? 'الزبون رفض. عرض بديل: '+altP.json.product_name+' ب'+altP.json.price : 'اعتذر بأدب.';
} else if (mentionedPrice && mainProduct) {
  instruction = 'عرض: ' + productInfo;
} else if (detected && productAll.length>0 && mainProduct) {
  instruction = 'الزبون يسأل عن ' + detected + '. اعرض: ' + productInfo + '. اسأله: واش مهتم؟';
} else if (detected && productAll.length===0) {
  instruction = detected + ' غير متوفر. عندنا: ' + categoriesStr;
} else if (d.intent==='inquiry') {
  instruction = mainProduct ? 'اعرض: ' + productInfo + '. اسأله: واش مهتم؟' : 'اشرح: ' + categoriesStr;
} else if (d.intent==='price') {
  instruction = 'الأسعار: ' + allPrices;
} else if (d.intent==='support') {
  instruction = 'الزبون عنده مشكلة. ساعده.';
} else if (messageCount >= 2) {
  instruction = 'زبون عائد. استقبله بجملة ترحيب مختلفة فقط. لا تذكر منتجات.';
} else {
  instruction = 'رحّب بجملة واحدة قصيرة فقط. لا تعرض منتجات حتى يسأل.';
}

const systemPrompt = `أنت بائع محترف في AykoShop للمنتجات الرقمية.
المنتجات: [${available.map(p=>p.json.product_name+' ب'+p.json.price).join(', ')}]
قواعد:
1. اللغة الافتراضية هي العربية الفصحى. لكن إذا كتب الزبون بالدارجة المغربية (حتى بحروف لاتينية مثل: slm, cava, bghit, hdr haka, labas) جاوب بالدارجة، وإذا كتب بالإنجليزية جاوب بالإنجليزية. طابق لغة الزبون.
2. جملتين قصيرتين فقط - لا أكثر
3. أنت بائع بشري محترف وذكي - لا تذكر أبداً أنك AI أو بوت
4. لا تكتب أي رابط أو URL في ردودك أبداً - ممنوع تماماً
5. لا تقل "آسف" أو "للأسف" أو "ما نقدرش" أو "ما كاينش"
6. كن متنوعاً جداً ومقنعاً في البيع - لا تكرر نفس الجملة أو نفس الترحيب مرتين
7. طرق الدفع الوحيدة المتاحة هي: Cash Plus، Wafacash، CIH Bank، Barid Bank، Binance. ممنوع منعاً باتاً ذكر أي بنك أو طريقة أخرى (مثل BMCE، التجاري، الشعبي، PayPal، Visa...). لا تذكر مدة التسليم (5-15 دقيقة) إلا في مرحلة الدفع فقط
8. كي زبون يقول "سلام/مرحبا/هلا/slm/hi" => رد بترحيب قصير متنوع فقط، بدون ذكر أي منتج
9. أنت ترسل صور الحسابات بشكل طبيعي. لا تقل أبداً "تواصل معنا لعرض الصور" أو "لا يمكنني عرض الصورة" - الصورة تُرسل تلقائياً مع ردك. عند طلب رؤية حساب قدّم الحساب بحماس واسأل إن أعجبه
${instruction}`;

let aiReply = '';
if (specialReply) {
  aiReply = specialReply;
} else {
  const messages = [{ role: 'system', content: systemPrompt }];
  for (const h of chatHistory.slice(-8)) messages.push({ role: h.role, content: h.message||h.content||'' });
  messages.push({ role: 'user', content: d.message });
  const response = await this.helpers.httpRequest({ method: 'POST', url: 'https://api.openai.com/v1/chat/completions', headers: { 'Authorization': OPENAI_KEY, 'Content-Type': 'application/json' }, body: { model: 'gpt-4o', max_tokens: 200, temperature: 0.9, messages } });
  aiReply = response.choices[0].message.content.replace(/\n/g,' ').trim();
}

try {
  await this.helpers.httpRequest({ method: 'POST', url: 'https://api.manychat.com/fb/subscriber/setCustomFieldByName', headers: { 'Authorization': MANYCHAT_KEY, 'Content-Type': 'application/json' }, body: { subscriber_id: d.subscriber_id, field_name: 'ai_reply', field_value: aiReply } });
} catch(e) {}

try {
  const img2 = (imageUrl && imageUrl.startsWith('http')) ? imageUrl : '';
  await this.helpers.httpRequest({ method: 'POST', url: 'https://api.manychat.com/fb/subscriber/setCustomFieldByName', headers: { 'Authorization': MANYCHAT_KEY, 'Content-Type': 'application/json' }, body: { subscriber_id: d.subscriber_id, field_name: 'ai_image2', field_value: img2 } });
} catch(e) {}

if (stopChatNow) {
  try {
    await this.helpers.httpRequest({ method: 'POST', url: 'https://api.telegram.org/bot' + TELEGRAM_BOT + '/sendMessage', headers: { 'Content-Type': 'application/json' }, body: { chat_id: ADMIN_CHAT, text: '🟡 زبون بغا طريقة دفع ماكايناش! كمّل معاه نتا 👇\n👤 ' + (d.customer_name||'') + '\n💬 ' + (d.message||'') + '\n📱 ' + channel + '\n🔗 ' + (d.manychat_link||'') + '\n\n🔇 نقر هنا باش يسكت البوت: /stopchat ' + d.subscriber_id + '\n🔊 باش يرجع البوت من بعد: /publicchat ' + d.subscriber_id } });
  } catch(e) {}
}

const finalAlertNeeded = alertOverride ? false : d.alert_needed;

return [{ json: { subscriber_id: d.subscriber_id, customer_name: d.customer_name, channel, customer_message: d.message, intent: d.intent, new_stage: d.new_stage, total_messages: 1, alert_needed: finalAlertNeeded, alert_emoji: d.alert_emoji, alert_reason: d.alert_reason, manychat_link: d.manychat_link, image_url: imageUrl, wa_phone: d.wa_phone, interested_in: mainProduct ? mainProduct.json.product_name : '', ai_reply: aiReply } }];

